    // We cannot change msg.sender when calling c from this contract, so we simulate owner vs non-owner by
    // deploying C externally in the harness with its owner set; here we only observe behavior relative to c.owner()
    function run(uint deposit, address payable recipient) public payable {
        require(address(this).balance >= deposit);
        // read owner and c balance before
        address ownerBefore = c.owner();
        uint balanceBefore = address(c).balance;
        // send deposit into contract C to set up funds
        if (deposit > 0) {
            // send Ether to C via its fallback
            (bool s,) = address(c).call{value: deposit}("");
            // ignore success; if call fails, balances reflect that
        }
        uint balanceMid = address(c).balance;
        // Attempt withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balanceAfter = address(c).balance;
        // Determine recipient balance change (observe this contract's balance cannot be recipient unless recipient==address(this))
        // We can only reliably observe recipient when recipient == address(this)
        uint recipientBalanceAfter = recipient.balance;
        // If caller (this contract) is owner, withdrawAll must not revert and must zero-out C's balance
        // If caller is not owner, withdrawAll must revert and C's balance must be unchanged from before the call
        bool callerIsOwner = (ownerBefore == address(this));
        if (callerIsOwner) {
            assert(reverted == false && balanceAfter == 0);
        } else {
            assert(reverted == true && balanceAfter == balanceMid);
        }
    }
