contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes the owner address, a recipient, and an amount of Ether to send into c first
    function run(address possibleOwner, address payable recipient, uint amount) public payable {
        require(address(this).balance >= amount);

        // Deploy-time owner of c is whatever was used when the checker deployed it; we only observe c.owner()
        address actualOwner = c.owner();

        // Fund c by sending Ether from this test to c
        // Ensure we have the funds in this contract
        (bool sent,) = address(c).call{value: amount}("\x00");
        // call to fallback may succeed or fail, but we don't require success. We just attempt to fund c.

        // Record balances before withdraw
        uint balBeforeC = address(c).balance;
        uint balBeforeThis = address(this).balance;

        // Attempt withdrawAll and catch revert
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfterC = address(c).balance;
        uint balAfterThis = address(this).balance;

        // General rule: if call did NOT revert, then the caller must have been the owner,
        // and C's balance becomes zero, and this contract's balance increases by exactly the amount taken from C.
        assert(
            reverted || (
                actualOwner == address(this) &&
                balAfterC == 0 &&
                balAfterThis == balBeforeThis + balBeforeC - (balBeforeC - balAfterC)
            )
        );
    }

    receive() external payable {}
}

