contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry used by the checker; takes owner, caller, recipient and an amount to fund C
    function run(address ownerAddr, address caller, address recipient, uint256 fund) public payable {
        require(true);
        // fund the contract c by sending Ether from this test contract
        // ensure this contract has enough balance to forward 'fund'
        if (fund > 0) {
            require(address(this).balance >= fund);
            // send Ether to c using its fallback
            (bool sent,) = address(c).call{value: fund}("");
            require(sent);
        }

        // read balance before attempting withdrawal
        uint256 before = address(c).balance;
        // read owner value from c
        address cOwner = c.owner();

        // determine whether the attempted caller is the recorded owner
        bool callerIsOwner = (caller == cOwner);

        // try to perform withdrawAll from the perspective of 'caller'
        bool reverted;
        // We need to perform the call as if made by 'caller'. The checker runs the transaction once
        // with msg.sender == this contract, so simulate call by using low-level call to c.withdrawAll
        // but include "caller" by encoding its address as a parameter; that does not change msg.sender
        // Since we cannot change msg.sender, we instead check the behavior for the current msg.sender
        // by comparing caller to address(this) and only invoking when they match; otherwise we still
        // attempt a call to observe revert behavior (which will reflect actual msg.sender == address(this)).

        // If caller != address(this), we still perform a call to observe behavior under actual msg.sender.
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = address(c).balance;
        uint256 receivedByThis = address(this).balance; // how much this contract holds after

        // The general rule (assert): If the actual msg.sender of the withdrawAll call (which is address(this))
        // equals the owner stored in c, the call must not revert and the contract's balance must drop to 0
        // and the recipient must have received exactly 'before'. If msg.sender is not the owner, the call must revert
        // and the contract balance must be unchanged.
        bool actualSenderIsOwner = (address(this) == cOwner);

        if (actualSenderIsOwner) {
            // success path: must not revert and all funds moved out of c
            assert(!reverted && after == 0);
        } else {
            // failure path: must revert and balance unchanged
            assert(reverted && after == before);
        }
    }

    receive() external payable { }
}

