    // single public test function taking parameters to exercise behavior
    function run(address deployerOwner, address caller, address payable recipient, uint256 deposit) public payable {
        require(deployerOwner != address(0) && caller != address(0) && recipient != address(0));
        // Ensure this contract has enough balance to deposit into c if asked
        if (deposit > 0) {
            require(address(this).balance >= deposit);
            // send Ether to c by calling its fallback (payable) via a low-level call
            (bool ok,) = address(c).call{value: deposit}("");
            require(ok);
        }

        // Read observable pre-state
        uint256 beforeC = address(c).balance;
        address ownerBefore = c.owner();

        // Decide which sender should call withdrawAll: simulate by using two branches
        // But we cannot change msg.sender for calls from this contract; instead we reason as follows:
        // If the test contract is the owner, then calling withdrawAll should succeed; otherwise it should revert.
        // To simulate both cases we will check both possibilities by interpreting 'caller' param:
        // - If caller == address(this) then this contract is the caller. We assert the rule relative to ownerBefore.
        // Since we cannot change msg.sender dynamically, we use only this contract's call and express rule in terms of ownerBefore and whether the call reverts.

        // Make the call as this contract (msg.sender == address(this)) and capture revert flag
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable post-state
        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule asserted:
        // If this contract was ownerBefore then withdrawAll must not revert and contract balance must drop to 0 and recipient must have received the funds (observed via this contract balance change is <= not reliable for recipient, so we assert c balance moved to 0 and if revert==false then beforeC==beforeC and afterC==0).
        // If this contract was not ownerBefore then the call must revert and contract balance must be unchanged.
        assert((ownerBefore == address(this) && reverted == false && afterC == 0) || (ownerBefore != address(this) && reverted == true && afterC == beforeC));
    }

    // allow receiving Ether so tests can top up this contract
    receive() external payable {}
