    constructor(C _c) { c = _c; }

    // single public test function taking parameters: callerIsOwner decides who calls withdrawAll;
    // recipient receives funds; amount funds the contract before withdraw.
    function run(bool callerIsOwner, address payable recipient, uint256 amount) public payable {
        require(recipient != address(0));
        // fund this test contract so it can forward Ether to c if needed
        require(address(this).balance >= amount);

        // initial owner as set in c during deployment is accessible via c.owner()
        address owner = c.owner();

        // send amount to c so it has a balance to withdraw
        // must ensure transfer occurs: call c.fallback by sending value
        // do the top-level state-changing call
        (bool sent,) = address(c).call{value: amount}("");
        require(sent);

        uint256 beforeBalance = address(c).balance;

        bool withdrew;
        bool reverted;

        // Decide caller: if callerIsOwner = true we want to call withdrawAll from this contract only if this contract is owner.
        // But the checker deploys c with owner set to some address; we cannot change msg.sender for calls.
        // So to have two cases, we simulate by checking whether this contract is owner. If callerIsOwner==true but this contract isn't owner,
        // the intended scenario is impossible; in that case we require owner==address(this) when callerIsOwner is true.
        if (callerIsOwner) {
            require(owner == address(this));
        } else {
            require(owner != address(this));
        }

        // Now perform the withdrawAll call, capturing revert
        try c.withdrawAll(recipient) {
            reverted = false;
            withdrew = true;
        } catch {
            reverted = true;
            withdrew = false;
        }

        uint256 afterBalance = address(c).balance;

        // General rule asserted:
        // - If caller was owner (i.e. owner == address(this)) then call must not revert, all Ether moved to recipient and contract balance is zero.
        // - If caller was not owner then call must revert and contract balance unchanged.
        assert(
            (callerIsOwner && !reverted && beforeBalance == afterBalance + 0 /*placeholder*/ && afterBalance == 0) ||
            (!callerIsOwner && reverted && afterBalance == beforeBalance)
        );
    }

    // allow receiving Ether for funding
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the whole test.
    // Parameters:
    // - useOwnerCall: if true, we require that this test contract is the owner so the call can be from owner; otherwise require it's not owner.
    // - recipient: address to receive withdrawn funds (must be non-zero)
    // - amount: Ether amount to fund c before withdraw; this function must be called with enough msg.value to cover it.
    function run(bool useOwnerCall, address payable recipient, uint256 amount) public payable {
        require(recipient != address(0));
        // Ensure we have funds to forward to c if needed
        require(address(this).balance >= amount);

        // Observe owner
        address owner = c.owner();

        // Enforce caller-role scenario: if useOwnerCall true, this contract must be owner so that calling c.withdrawAll is from owner.
        if (useOwnerCall) {
            require(owner == address(this));
        } else {
            require(owner != address(this));
        }

        // Fund C by sending Ether to its fallback
        (bool funded, ) = address(c).call{value: amount}("");
        require(funded);

        uint256 beforeBalance = address(c).balance;

        // Perform the state-changing call on c as a top-level statement and capture revert.
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;

        // Assert the general invariant:
        // - If call was from owner (useOwnerCall==true) it must not revert and C's balance becomes zero and decrease equals beforeBalance.
        // - If call was from non-owner it must revert and C's balance is unchanged.
        assert(
            (useOwnerCall && !reverted && afterBalance == 0) ||
            (!useOwnerCall && reverted && afterBalance == beforeBalance)
        );
    }

    // Allow receiving Ether
    receive() external payable { }
}

