contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: inputs are a potential caller address and a recipient and an amount
    function run(address caller, address payable recipient, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // set up: ensure this test contract is owner of c by reading c.owner()
        address ownerBefore = c.owner();
        // read contract balance before
        uint256 cBalBefore = address(c).balance;
        // read this contract balance before (used to check received funds when owner withdraws to us)
        uint256 thisBalBefore = address(this).balance;

        // We will simulate calls from either the owner or a non-owner.
        // If caller equals the stored owner, perform withdrawAll as owner by calling c.withdrawAll from this contract
        // (note: msg.sender for c will be this contract). To simulate the case where the owner is this contract,
        // we only call withdraw when ownerBefore == address(this). Otherwise the call must revert if caller is not owner.

        bool reverted;
        // perform the call and capture whether it reverted
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balances and owner after
        uint256 cBalAfter = address(c).balance;
        uint256 thisBalAfter = address(this).balance;
        address ownerAfter = c.owner();

        // General invariant to assert:
        // - owner field never changes as withdrawAll does not modify owner
        // - If this contract was ownerBefore, withdrawAll must not revert and c balance should become zero and recipient (if equal to this) gets the funds
        // - If this contract was not ownerBefore, withdrawAll must revert and c balance must be unchanged

        assert(
            ownerAfter == ownerBefore
            && (
                (ownerBefore == address(this) && reverted == false && cBalAfter == 0 && thisBalAfter == thisBalBefore + cBalBefore && cBalBefore >= 0)
                || (ownerBefore != address(this) && reverted == true && cBalAfter == cBalBefore)
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function driving C and asserting the invariant.
    // Params: recipient to pass to withdrawAll.
    function run(address payable recipient) public payable {
        // read observable before-values
        address ownerBefore = c.owner();
        uint256 cBalBefore = address(c).balance;

        // perform the call and record whether it reverted
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observable after-values
        address ownerAfter = c.owner();
        uint256 cBalAfter = address(c).balance;

        // General rule:
        // 1) owner never changes
        // 2) if call reverted, contract balance must be unchanged
        // 3) if call did not revert, contract balance must be zero (all funds transferred out)
        assert(
            ownerAfter == ownerBefore
            && (reverted ? cBalAfter == cBalBefore : cBalAfter == 0)
        );
    }

    receive() external payable { }
}

