contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test takes a candidate caller address and an amount to fund C with, and a recipient.
    // We simulate calls by having this contract (the deployer of c) call c; msg.sender for c calls
    // will be this contract. To model non-owner vs owner behavior, we rely on c.owner() getter.
    function run(address payable recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount, "insufficient balance to fund");
        // Fund contract c by sending Ether to its fallback
        (bool sent,) = address(c).call{value: fundAmount}("");
        // record balances and owner
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;
        address owner = c.owner();

        // Decide whether this contract is owner observedly
        bool isOwner = (owner == address(this));

        // Try to withdraw all to the provided recipient and record whether it reverted
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;
        uint256 afterRecipient = recipient.balance;

        // General rule:
        // If the caller (this) is owner then the call must not revert and all Ether moves from c to recipient.
        // If the caller is not owner then either the call reverted, or nothing moved from c to recipient nor to this.
        assert(
            (isOwner && !reverted && beforeC == fundAmount && afterC == 0 && afterRecipient >= beforeThis /* recipient may be any address, but must have received funds: check c decreased */) ||
            (!isOwner && (reverted || (afterC == beforeC && afterRecipient == recipient.balance && afterThis <= beforeThis)))
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params: recipient to receive withdrawn funds, amount to fund C with.
    function run(address payable recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount, "insufficient balance to fund");

        // Fund contract c by sending Ether to its fallback
        (bool ok,) = address(c).call{value: fundAmount}("");
        require(ok, "funding failed");

        // Snapshot balances and owner
        uint256 beforeC = address(c).balance;
        address owner = c.owner();
        bool amOwner = (owner == address(this));

        // Attempt withdrawAll and record whether it reverted
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterRecipient = recipient.balance;

        // General rule:
        // If this contract is owner then withdrawAll must not revert and must drain C to recipient.
        // If this contract is not owner then either the call reverted or C's balance is unchanged.
        assert(
            (amOwner && !reverted && beforeC > 0 && afterC == 0) ||
            (!amOwner && (reverted || afterC == beforeC))
        );
    }

    receive() external payable { }
}

